Repo* currentRepo(){return repoIndex>=0&&size_t(repoIndex)<repos.size()?&repos[repoIndex]:nullptr;}
Builder* currentBuilder(){return builderIndex>=0&&size_t(builderIndex)<builders.size()?&builders[builderIndex]:nullptr;}
