static std::string items(const std::vector<std::string>& names){std::string s;for(auto& name:names){s+=name;s+='\0';}s+='\0';return s;}
void clearPreview(){preview={};previewKey=0;if(AL_HAS(preview_lines))host->preview_lines(nullptr,0);}
