void error(const std::exception& e){message="ERROR: "+std::string(e.what());}
bool button(const std::string& s){return host->button(s.c_str())!=0;}
bool integer(const std::string& s,int& n){if(host->input_int(s.c_str(),&n)){changed();return true;}return false;}
bool real(const std::string& s,float& n){if(host->input_float(s.c_str(),&n)){if(!std::isfinite(n))n=0;changed();return true;}return false;}
bool real64(const std::string& s,double& n){float f=float(n);if(real(s,f)){n=f;return true;}return false;}
