void line(const std::string& s){host->text(s.c_str());}
static std::string axisLabel(const std::string& name,int a){auto at=name.find("##");return (at==name.npos?name:name.substr(0,at))+" "+"XYZ"[a]+(at==name.npos?"":name.substr(at));}
